pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // Initialize the contract and set the caller as owner
        c.initialize();

        // Make the caller the owner by transferring ownership to itself
        vm.prank(address(this));
        c.transferOwnership(caller);

        // Now the caller is the owner, and attempts to renounce ownership.
        // The correct behavior is that owner() becomes address(0).
        // The mutant will set owner() to caller instead due to the changed _transferOwnership.
        vm.prank(caller);
        c.renounceOwnership();

        // After renouncing ownership, the owner must be the zero address.
        assertTrue(c.owner() == address(0));
    }
}

