pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller, uint8 initializingStatus) public {
        // 1. Admissible domain: newOwner must be non-zero (transferOwnership reverts if newOwner == address(0) regardless),
        // caller must not be the owner, and we need the contract in a non-initializing / initialized state.
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(this));
        // After setUp, the deployer (this) is the owner. Ensure initializing status is not interfering.
        // The contract has no public getter for _initializing, so we cannot read it, but we 
        // bound the fuzzer to call transferOwnership without any special state.

        // 2. Drive the transfer
        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // 3. Assert the general rule: ownership only changes if the operation succeeded.
        // The new owner (after a successful call) should be newOwner; after a failed call, the owner should remain the deployer.
        // In the correct contract, a non-owner call will revert, so ok == false and owner() remains this.
        // In the buggy contract, a non-owner call will succeed (ok == true) and owner() becomes newOwner.
        assertTrue(!ok || c.owner() == newOwner, "ownership rule violated");
    }
}

